def describe(x, indent='', depth=0, maxdepth=3):
    if depth>maxdepth: return
    if isinstance(x, np.ndarray):
        print(indent, 'ndarray', x.shape, x.dtype)
        if x.dtype.names:
            print(indent, 'fields', x.dtype.names)
            if x.size: describe(x.flat[0],indent+'  ',depth+1,maxdepth)
        elif x.dtype==object and x.size:
            for i,v in enumerate(x.flat[:min(3,x.size)]):
                print(indent,f'[{i}]'); describe(v,indent+'  ',depth+1,maxdepth)
        elif x.size and x.size<20: print(indent,'values',x.ravel().tolist())
    elif hasattr(x,'_fieldnames'):
        print(indent,'mat_struct fields',x._fieldnames)
        for f in x._fieldnames:
            v=getattr(x,f); print(indent,f+'.'); describe(v,indent+'  ',depth+1,maxdepth)
