from pathlib import Path
A={'excellent','great','good','fair','multi'}
def ch(ds):return ''.join(chr(int(x)) for x in ds[()].ravel(order='F') if x).strip()
def strs(f,ds):
 return [ch(f[r]) for r in ds[()].ravel(order='F')] if ds.dtype==h5py.ref_dtype else [ch(ds)]
for p in sorted(Path('/app/data/Ephys_Behavior').glob('data_structure_*.mat')):
