  clu=f['obj/clu']; cgs=[f[r] for r in clu[()].ravel(order='F')] if isinstance(clu,h5py.Dataset) else [clu]
  meta=f['obj/meta']; probe=meta['probe'];
  locs=strs(f,probe['loc']) if isinstance(probe,h5py.Group) and 'loc' in probe else []
  vals=[]
  for i,g in enumerate(cgs):
